    "explanation": "Respuesta correcta: Asma\n🧠 ANÁLISIS DE LA PREGUNTA\nEl asma se caracteriza por una limitación reversible del flujo aéreo, por lo que se clasifica como enfermedad obstructiva. La fibrosis pulmonar idiopática es restrictiva parenquimatosa, la embolia pulmonar corresponde a una neumopatía vascular, la miastenia grave produce restricción por debilidad neuromuscular y el derrame pleural crónico ocasiona restricción por compromiso pleural.\n🔑 CONCEPTOS CLAVE\n- El asma pertenece al grupo de enfermedades obstructivas.\n- Las enfermedades obstructivas afectan principalmente las vías respiratorias.\n- No todas las enfermedades pulmonares producen el mismo patrón funcional.\n⚡ REPASO ACTIVO\n\n**<u>Fisiopatología obstructiva (vías respiratorias)</u>**\n- Asma.\n- Enfermedad pulmonar obstructiva crónica (EPOC).\n- Bronquiectasias.\n- Bronquiolitis.\n\n**<u>Fisiopatología restrictiva (enfermedad parenquimatosa)</u>**\n- Fibrosis pulmonar idiopática.\n- Asbestosis.\n- Neumonitis intersticial descamativa.\n- Sarcoidosis.\n\n**<u>Fisiopatología restrictiva (debilidad neuromuscular)</u>**\n- Esclerosis lateral amiotrófica.\n- Síndrome de Guillain-Barré.\n- Miastenia grave.\n\n**<u>Fisiopatología restrictiva (enfermedad pleural o de la pared torácica)</u>**\n- Cifoescoliosis.\n- Espondilitis anquilosante.\n- Derrame pleural crónico.\n\n**<u>Neumopatías vasculares</u>**\n- Embolia pulmonar.\n- Hipertensión arterial pulmonar.\n- Enfermedad pulmonar venooclusiva.\n- Vasculitis.\n\n**<u>Neoplasias malignas</u>**\n- Carcinoma broncógeno.\n- Enfermedad metastásica.\n\n**<u>Enfermedades infecciosas</u>**\n- Neumonía.\n- Bronquitis.\n- Traqueítis.\n\n📖 Referencia: Harrison. Principios de Medicina Interna, 21.ª edición, capítulo 284, cuadro 284-1.",
