    "explanation": "Respuesta correcta: La inflamación tipo 2 aparece solo ante exposición a alérgenos.\n🧠 ANÁLISIS DE LA PREGUNTA\nLa inflamación tipo 2 no se limita a los alérgenos. También puede iniciarse por irritantes, contaminantes, agentes oxidantes, hongos o virus. Los procesos tipo 2 y no tipo 2 pueden coexistir.\n🔑 CONCEPTOS CLAVE\n- La inflamación tipo 2 puede ser alérgica o no alérgica.\n- La inflamación no tipo 2 puede ser neutrofílica.\n- Ambos patrones pueden presentarse simultáneamente.\n⚡ REPASO ACTIVO\n\n**<u>Inflamación tipo 2:</u>**\n- Puede relacionarse con alérgenos.\n- Puede originarse por estímulos no alérgicos.\n- Se asocia con IgE y eosinófilos.\n- Participan IL-4, IL-5 e IL-13.\n\n**<u>Inflamación no tipo 2:</u>**\n- Puede coexistir con inflamación tipo 2.\n- Puede presentar predominio neutrofílico.\n- Es frecuente en el asma grave refractaria.\n- Puede relacionarse con infección crónica.\n- Incluye el asma paucigranulocítica.\n\n📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 287.",
