    "explanation": "Respuesta correcta: Eosinofilia periférica superior al 30% de los leucocitos.\n🧠 ANÁLISIS DE LA PREGUNTA\nCerca del 90% de los pacientes presenta eosinofilia periférica, con un promedio mayor del 30% del total de leucocitos. La eosinofilia en el lavado broncoalveolar también apoya el diagnóstico.\n🔑 CONCEPTOS CLAVE\n- La eosinofilia periférica es frecuente.\n- El lavado broncoalveolar puede mostrar eosinofilia.\n- La respuesta a corticosteroides suele ser rápida.\n⚡ REPASO ACTIVO\n- Eosinofilia periférica en aproximadamente 90%.\n- Promedio de eosinófilos mayor del 30%.\n- Eosinófilos en lavado broncoalveolar cercanos al 40%.\n- Infiltrados periféricos o pleurales migratorios.\n- Respuesta rápida a corticosteroides.\n- Recidiva frecuente al suspender el tratamiento.\n\n📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 288.",
