    "correctOptionIndex": 1,
    "explanation": "Respuesta correcta: La forma crónica presenta opacidades periféricas, descritas como edema pulmonar negativo.\n🧠 ANÁLISIS DE LA PREGUNTA\nLa neumonía eosinofílica crónica presenta opacidades migratorias periféricas o pleurales, patrón denominado “negativo fotográfico del edema pulmonar”. La forma aguda tiene inicio rápido, infiltrados difusos y eosinofilia periférica generalmente tardía.\n🔑 CONCEPTOS CLAVE\n- Aguda: inicio menor de un mes e insuficiencia respiratoria hipoxémica.\n- Crónica: evolución de semanas o meses y eosinofilia periférica frecuente.\n- El edema pulmonar negativo corresponde a infiltrados periféricos de la forma crónica.\n⚡ REPASO ACTIVO\n\n**<u>Neumonía eosinofílica aguda:</u>**\n- Inicio menor de un mes.\n- Infiltrados pulmonares difusos.\n- Eosinófilos en lavado broncoalveolar mayores del 25%.\n- Eosinofilia periférica ausente o tardía.\n- Insuficiencia respiratoria que puede requerir ventilación mecánica.\n- Respuesta rápida a corticosteroides.\n- No suele recidivar al suspenderlos.\n\n**<u>Neumonía eosinofílica crónica:</u>**\n\n**<u>Evolución durante semanas o meses.</u>**\n- Frecuente en mujeres no fumadoras.\n- Asociación habitual con asma o alergias.\n- Eosinofilia periférica presente en cerca del 90%.\n- Opacidades periféricas o pleurales migratorias.\n- Patrón de “negativo fotográfico del edema pulmonar”.\n- Respuesta rápida a corticosteroides.\n- Recidiva frecuente al suspenderlos.\n\n📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 288.",
