    "explanation": "Respuesta correcta: El mesotelioma se relaciona estrechamente con el consumo de tabaco.\n🧠 ANÁLISIS DE LA PREGUNTA\nEl mesotelioma pleural o peritoneal se relaciona con la exposición al asbesto, pero no muestra una asociación clara con el tabaquismo. En cambio, el tabaco y el asbesto aumentan conjuntamente el riesgo de cáncer pulmonar.\n🔑 CONCEPTOS CLAVE\n- La asbestosis es una fibrosis intersticial difusa.\n- Las placas pleurales son un marcador de exposición.\n- El tabaquismo potencia el riesgo de cáncer pulmonar, no de mesotelioma.\n⚡ REPASO ACTIVO\n\n**<u>Manifestaciones pulmonares:</u>**\n- Fibrosis intersticial difusa.\n- Opacidades lineales o irregulares basales.\n- Reticulación subpleural.\n- Patrón funcional restrictivo.\n- Disminución de la capacidad de difusión.\n- Obstrucción leve ocasional.\n\n**<u>Manifestaciones pleurales:</u>**\n- Placas pleurales.\n- Engrosamiento o calcificación pleural.\n- Predominio en bases, diafragma y borde cardíaco.\n- Derrames pleurales benignos.\n- Indican exposición, pero no fibrosis pulmonar.\n\n**<u>Neoplasias asociadas:</u>**\n- Cáncer pulmonar.\n- Mesotelioma pleural.\n- Mesotelioma peritoneal.\n- El tabaco incrementa el riesgo de cáncer pulmonar.\n- El tabaco no se relaciona claramente con mesotelioma.\n\n📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 289, figura 289-1.",
