    "explanation": "Respuesta correcta: Artritis reumatoide.\n🧠 ANÁLISIS DE LA PREGUNTA\nLa artritis reumatoide pertenece al grupo de enfermedades autoinmunitarias asociadas a bronquiectasias. En cambio, fibrosis quística, síndrome de Kartagener, síndrome de cilios discinéticos y deficiencia de α1-antitripsina forman parte de las causas genéticas.\n🔑 CONCEPTOS CLAVE\n- Las causas genéticas incluyen fibrosis quística.\n- El síndrome de Kartagener es una causa clásica.\n- La artritis reumatoide es una causa autoinmunitaria.\n⚡ REPASO ACTIVO\n\n**<u>Causas genéticas:</u>**\n- Fibrosis quística.\n- Síndrome de Kartagener.\n- Deficiencia de α1-antitripsina.\n- Síndrome de cilios discinéticos.\n\n**<u>Estudios recomendados:</u>**\n- Cloro en sudor.\n- Concentración de α1-antitripsina.\n- Cepillado o biopsia nasal.\n- Pruebas genéticas.\n\n📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 290, cuadro 290-1.",
