    "correctOptionIndex": 1,
    "explanation": "Respuesta correcta: Bronquio con diámetro mayor que el vaso adyacente.\n🧠 ANÁLISIS DE LA PREGUNTA\nLa dilatación bronquial se reconoce cuando el diámetro de la vía respiratoria es al menos 1,5 veces mayor que el del vaso acompañante, hallazgo denominado signo del anillo de sello.\n🔑 CONCEPTOS CLAVE\n- La tomografía es el estudio de elección.\n- El signo del anillo de sello indica dilatación bronquial.\n- También puede observarse ausencia de estrechamiento bronquial.\n⚡ REPASO ACTIVO\n- Dilatación de las vías respiratorias.\n- Signo del anillo de sello.\n- Bronquio al menos 1,5 veces mayor que el vaso adyacente.\n- Falta de estrechamiento gradual de los bronquios.\n- Estructuras tubulares a menos de 1 cm de la pleura.\n- Engrosamiento de la pared bronquial.\n- Secreciones espesas.\n- Patrón de árbol en capullo.\n- Quistes originados en la pared bronquial.\n\n📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 290, figura 290-1.",
