    "explanation": "Respuesta correcta: Los sujetos PiMZ no fumadores requieren terapia de aumento de rutina.\n🧠 ANÁLISIS DE LA PREGUNTA\nLa terapia de aumento de α1-antitripsina no se recomienda en sujetos heterocigotos PiMZ. Este tratamiento está disponible para pacientes con deficiencia grave, mientras que el tabaquismo aumenta especialmente el riesgo de EPOC temprana en individuos PiZZ.\n🔑 CONCEPTOS CLAVE\n- El alelo M se asocia con valores normales de α1-antitripsina.\n- El genotipo PiZZ constituye la forma grave más frecuente.\n- El tabaquismo acelera la aparición de EPOC en pacientes con deficiencia grave.\n⚡ REPASO ACTIVO\n\n**<u>Variantes alélicas:</u>**\n- Alelo M: concentración normal.\n- Alelo S: reducción leve.\n- Alelo Z: reducción marcada.\n- Alelo nulo: ausencia de producción.\n\n**<u>Deficiencia grave:</u>**\n- Genotipo PiZZ.\n- Combinación de alelo Z y alelo nulo.\n- Puede causar EPOC de inicio temprano.\n\n**<u>Factores relacionados con EPOC:</u>**\n- Tabaquismo.\n- Sexo masculino.\n- Otros factores genéticos o ambientales.\n\n**<u>Diagnóstico y tratamiento:</u>**\n- Medición sérica inmunitaria de α1-antitripsina.\n- Terapia de aumento intravenosa semanal en deficiencia grave.\n- No se recomienda terapia de aumento en sujetos PiMZ.\n\n📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 292.",
