    "correctOptionIndex": 0,
    "explanation": "Respuesta correcta: Los antibióticos suelen indicarse en exacerbaciones moderadas o graves.\n🧠 ANÁLISIS DE LA PREGUNTA\nLas exacerbaciones moderadas o graves suelen tratarse con antibióticos, incluso sin identificar un patógeno específico. Los glucocorticoides sistémicos acortan la estancia y aceleran la recuperación; se sugieren 30 a 40 mg de prednisona durante cerca de 5 a 10 días.\n🔑 CONCEPTOS CLAVE\n- Los antibióticos se usan en exacerbaciones moderadas o graves.\n- La elección depende de la sensibilidad local y del estado clínico.\n- Los glucocorticoides sistémicos favorecen una recuperación más rápida.\n⚡ REPASO ACTIVO\n\n**<u>Bacterias relacionadas:</u>**\n- Streptococcus pneumoniae.\n- Haemophilus influenzae.\n- Moraxella catarrhalis.\n\n**<u>Bacterias menos frecuentes:</u>**\n- Mycoplasma pneumoniae.\n- Chlamydia pneumoniae.\n\n**<u>Glucocorticoides:</u>**\n- Reducen la duración de la estancia.\n- Aceleran la recuperación.\n- Disminuyen recaídas posteriores.\n- Prednisona de 30 a 40 mg por vía oral.\n- Duración aproximada de 5 a 10 días.\n- Hiperglucemia como complicación frecuente.\n\n📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 292.",
