    "explanation": "Respuesta correcta: Su causa más frecuente es la enfermedad pulmonar obstructiva crónica.\n🧠 ANÁLISIS DE LA PREGUNTA\nLa mayoría de los neumotórax espontáneos secundarios se relaciona con enfermedad pulmonar obstructiva crónica, aunque puede ocurrir en prácticamente cualquier neumopatía.\n🔑 CONCEPTOS CLAVE\n- Aparece sobre una enfermedad pulmonar previa.\n- La causa principal es la enfermedad pulmonar obstructiva crónica.\n- Tiene mayor gravedad por la reserva pulmonar disminuida.\n⚡ REPASO ACTIVO\n\n**<u>Neumotórax primario:</u>**\n- Sin neumopatía conocida.\n- Rotura de ampollas apicales.\n- Asociación con tabaquismo.\n\n**<u>Neumotórax secundario:</u>**\n- Con neumopatía subyacente.\n- Causa más frecuente: enfermedad pulmonar obstructiva crónica.\n- Mayor riesgo vital.\n\n📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 294",
