    "explanation": "Respuesta correcta: Obesidad, sexo masculino y edad avanzada.\n🧠 ANÁLISIS DE LA PREGUNTA\nEl fragmento identifica a la obesidad, el sexo masculino y la edad avanzada como los principales factores de riesgo del SAHOS. Otros factores anatómicos, genéticos y endocrinos también pueden favorecerlo.\n🔑 CONCEPTOS CLAVE\n- La obesidad constituye un factor de riesgo fundamental.\n- La prevalencia es mayor en varones.\n- El riesgo aumenta con la edad.\n⚡ REPASO ACTIVO\n\n**<u>Factores principales:</u>**\n- Obesidad.\n- Sexo masculino.\n- Edad avanzada.\n\n**<u>Otros factores:</u>**\n- Retrognatia.\n- Micrognatia.\n- Antecedentes familiares.\n- Síndrome de Down.\n- Síndrome de Treacher-Collins.\n- Hipertrofia adenoamigdalina.\n- Menopausia.\n- Acromegalia.\n- Hipotiroidismo.\n\n📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 297.",
