    "correctOptionIndex": 1,
    "explanation": "Respuesta correcta: La ausencia de obesidad excluye completamente el diagnóstico.\n🧠 ANÁLISIS DE LA PREGUNTA\nAunque la obesidad es un factor de riesgo importante, su ausencia no excluye el SAHOS. También pueden intervenir alteraciones craneofaciales, hipertrofia adenoamigdalina, antecedentes familiares y enfermedades endocrinas.\n🔑 CONCEPTOS CLAVE\n- Entre 40% y 60% de los casos se atribuyen al exceso de peso.\n- Los individuos obesos tienen un riesgo aproximadamente cuatro veces mayor.\n- Un aumento de 10% del peso incrementa más de 30% el IAH.\n⚡ REPASO ACTIVO\n- Depósito de grasa alrededor de la vía respiratoria.\n- Reducción de la elasticidad de la pared torácica.\n- Disminución de los volúmenes pulmonares.\n- Menor tracción caudal sobre la faringe.\n- Mayor tendencia al colapso durante el sueño.\n- La ausencia de obesidad no descarta SAHOS.\n\n📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 297.",
