    "explanation": "Respuesta correcta: SAHOS moderado.\n🧠 ANÁLISIS DE LA PREGUNTA\nUn IAH entre 15 y 29 episodios por hora corresponde a SAHOS moderado. La clasificación también puede valorarse según la somnolencia y la hipoxemia asociadas.\n🔑 CONCEPTOS CLAVE\n- Leve: 5 a 14 episodios por hora.\n- Moderado: 15 a 29 episodios por hora.\n- Grave: 30 o más episodios por hora.\n⚡ REPASO ACTIVO\n\n**<u>IAH:</u>**\n- Número de apneas e hipopneas por hora de sueño.\n\n**<u>Clasificación:</u>**\n- SAHOS leve: 5-14 por hora.\n- SAHOS moderado: 15-29 por hora.\n- SAHOS grave: ≥30 por hora.\n\n**<u>La gravedad también considera:</u>**\n- Hipoxemia.\n- Somnolencia.\n- Fragmentación del sueño.\n- Alteración funcional.\n\n📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 297, cuadro 297-2.",
