    "correctOptionIndex": 0,
    "explanation": "Respuesta correcta: Presión positiva continua de la vía respiratoria.\n🧠 ANÁLISIS DE LA PREGUNTA\nLa presión positiva continua de la vía respiratoria constituye el tratamiento médico con mayor evidencia. Actúa como una férula neumática que mantiene abierta la vía respiratoria durante el sueño.\n🔑 CONCEPTOS CLAVE\n- Mantiene permeable la vía respiratoria.\n- Reduce apneas, hipopneas y despertares.\n- Mejora el intercambio gaseoso y la somnolencia.\n⚡ REPASO ACTIVO\n\n**<u>Tratamiento principal:</u>**\n- Presión positiva continua.\n\n**<u>Forma de administración:</u>**\n- Mascarilla nasal.\n- Mascarilla nasobucal.\n\n**<u>Beneficios:</u>**\n- Menos apneas e hipopneas.\n- Menos despertares.\n- Mejor intercambio gaseoso.\n- Mayor alerta.\n- Mejor ánimo y calidad de vida.\n- Reducción moderada de la presión arterial.\n\n📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 297.",
