    "explanation": "Respuesta correcta: Clase IV\n🧠 ANÁLISIS DE LA PREGUNTA\nLa clase IV corresponde a una nefritis lúpica difusa, que compromete ≥50% de los glomérulos y se subdivide en IV-S e IV-G.\n🔑 CONCEPTOS CLAVE\n≥50% de glomérulos.\nNefritis lúpica difusa.\nSubdivisión IV-S e IV-G.\n⚡ REPASO ACTIVO\nClase I: glomérulos normales en microscopía de luz; depósitos inmunitarios en el mesangio por inmunofluorescencia.\nClase II: hipercelularidad y/o expansión de la matriz mesangial con depósitos inmunitarios en el mesangio.\nClase III: glomerulonefritis focal (<50% de glomérulos), segmentaria o global, endocapilar o extracapilar, con depósitos subendoteliales circunscritos.\nIII (A): lesiones activas.\nIII (A/C): lesiones activas y crónicas.\nIII (C): lesiones crónicas inactivas con cicatrices glomerulares.\nClase IV: glomerulonefritis difusa (≥50% de glomérulos), segmentaria (IV-S) o global (IV-G), con depósitos subendoteliales difusos.\nIV-S (A): lesiones activas.\nIV-G (A): lesiones activas.\nIV-S (A/C): lesiones activas y crónicas.\nIV-G (A/C): lesiones activas y crónicas.\nIV-S (C): lesiones crónicas inactivas.\nIV-G (C): lesiones crónicas inactivas.\nClase V: nefritis lúpica membranosa con depósitos subepiteliales; puede coexistir con clases III o IV.\nClase VI: ≥90% de glomérulos esclerosados sin actividad residual.\n\n📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, Capítulo 356.",
