    "correctOptionIndex": 4,
    "explanation": "Respuesta correcta: Las erosiones articulares son frecuentes en las radiografías simples.\n🧠 ANÁLISIS DE LA PREGUNTA\nLas erosiones no son frecuentes en las radiografías; pueden detectarse mediante ecografía en una proporción importante de pacientes. Las demás afirmaciones corresponden al texto.\n🔑 CONCEPTOS CLAVE\nPoliartritis intermitente.\nDeformidades en 10%.\nDescartar necrosis isquémica ósea en monoartritis persistente.\nMialgias más frecuentes que miositis.\n⚡ REPASO ACTIVO\nMusculoesqueléticas: poliartritis intermitente con predominio en manos, muñecas y rodillas; deformidades articulares en 10%; erosiones poco frecuentes en radiografía, detectables por ecografía; descartar necrosis isquémica ósea ante artritis persistente; la mayoría presenta mialgias sin miositis; glucocorticoides y antipalúdicos pueden producir debilidad muscular.\n\n📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, Capítulo 356.",
