    "correctOptionIndex": 0,
    "explanation": "Respuesta correcta: La nefritis suele ser sintomática desde las etapas iniciales, por lo que el examen general de orina aporta poco al diagnóstico.\n🧠 ANÁLISIS DE LA PREGUNTA\nLa nefritis lúpica es asintomática en casi todos los pacientes, por lo que el texto enfatiza la importancia de realizar un análisis general de orina en todo paciente con sospecha de LES.\n🔑 CONCEPTOS CLAVE\nNefritis generalmente asintomática.\nBiopsia renal ante sospecha clínica.\nClase III y IV: hematuria y proteinuria >500 mg/24 h.\nControl de factores cardiovasculares.\n⚡ REPASO ACTIVO\nRenales: la nefritis es una de las manifestaciones más graves y suele ser asintomática; realizar examen general de orina en todo paciente con sospecha de LES; biopsia renal cuando existan indicios clínicos de nefritis; la nefritis proliferativa (clases III y IV) suele presentar hematuria y proteinuria >500 mg/24 h; cerca del 50% desarrolla síndrome nefrótico; puede evolucionar a nefropatía terminal; controlar inflamación sistémica, presión arterial, hiperlipidemia e hiperglucemia.\n\n📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, Capítulo 356.",
