    "explanation": "Respuesta correcta: La hipertensión pulmonar es una manifestación frecuente en la mayoría de los pacientes con LES.\n🧠 ANÁLISIS DE LA PREGUNTA\nLa hipertensión pulmonar ocurre solo en una pequeña proporción de pacientes con LES, no en la mayoría. Las demás afirmaciones corresponden al texto.\n🔑 CONCEPTOS CLAVE\nPleuritis = manifestación pulmonar más frecuente.\nInfiltrados pulmonares pueden simular infección.\nHemorragia intraalveolar y fibrosis pueden comprometer la vida.\n⚡ REPASO ACTIVO\nPulmonares: pleuritis con o sin derrame pleural (la más frecuente); responde a AINE si es leve y a glucocorticoides si es grave; infiltrados pulmonares difíciles de diferenciar de infección; fibrosis, síndrome de reacción pulmonar y hemorragia intraalveolar son manifestaciones graves; la hipertensión pulmonar ocurre en una pequeña proporción de pacientes.\n\n📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, Capítulo 356.",
