    "explanation": "Respuesta correcta: Se ha demostrado que los glucocorticoides mejoran claramente la miocarditis y la endocarditis lúpicas.\n🧠 ANÁLISIS DE LA PREGUNTA\nEl texto señala que no se ha comprobado que los glucocorticoides u otros inmunodepresores mejoren la miocarditis o la endocarditis por lupus.\n🔑 CONCEPTOS CLAVE\nPericarditis = manifestación cardíaca más frecuente.\nMiocarditis y Libman-Sacks = formas graves.\nMayor riesgo de infarto de miocardio.\n⚡ REPASO ACTIVO\nCardíacas: pericarditis como manifestación más frecuente; rara vez produce taponamiento; miocarditis y endocarditis de Libman-Sacks son las formas más graves; puede existir insuficiencia valvular mitral o aórtica y embolias; aumento del riesgo de insuficiencia cardíaca e infarto de miocardio; no está demostrado el beneficio de glucocorticoides sobre miocarditis o endocarditis.\n\n📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, Capítulo 356.",
