    "correctOptionIndex": 0,
    "explanation": "Respuesta correcta: La warfarina es segura durante el embarazo y constituye el anticoagulante de elección.\n🧠 ANÁLISIS DE LA PREGUNTA\nLa warfarina es teratógena y debe evitarse durante el embarazo. En pacientes con síndrome antifosfolípido y antecedentes de pérdidas fetales, el tratamiento recomendado es heparina (habitualmente de bajo peso molecular) asociada a ácido acetilsalicílico.\n🔑 CONCEPTOS CLAVE\nWarfarina: teratógena.\nHeparina + AAS: aumenta nacidos vivos.\nHidroxicloroquina debe mantenerse durante el embarazo.\nAzatioprina puede añadirse si persiste actividad.\n⚡ REPASO ACTIVO\nLa fertilidad suele ser normal, pero aumenta la tasa de abortos.\nMayor riesgo fetal con lupus activo, anticuerpos antifosfolípidos, hipertensión o nefritis activa.\nMantener hidroxicloroquina durante el embarazo.\nSi es necesario, usar prednisona o prednisolona en la menor dosis eficaz y el menor tiempo posible.\nSi persiste actividad, añadir azatioprina.\nMetotrexato y micofenolato deben evitarse por riesgo fetal demostrado.\nEn pérdidas fetales por SAF: heparina + ácido acetilsalicílico.\nWarfarina es teratógena.\nEvitar anticoagulantes orales directos durante el embarazo.\nAnticuerpos anti-Ro se asocian con lupus neonatal y bloqueo cardíaco congénito.\nLa hidroxicloroquina disminuye el riesgo de recurrencia del bloqueo cardíaco congénito.\n\n📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, Capítulo 356.",
