    "explanation": "Respuesta correcta: Trombocitopenia\n🧠 ANÁLISIS DE LA PREGUNTA\nLa trombocitopenia (30%) es la manifestación hematológica más frecuente, mientras que la anemia hemolítica autoinmunitaria ocurre en aproximadamente el 10%.\n🔑 CONCEPTOS CLAVE\nTrombocitopenia: 30%.\nAnemia hemolítica: 10%.\n⚡ REPASO ACTIVO\nVenosas: TVP (39%), livedo reticular (24%), embolia pulmonar (14%), tromboflebitis superficial (12%), trombosis en otros sitios (11%).\nArteriales: apoplejía (20%), Libman-Sacks (14%), AIT (11%), IAM/angina (10%), úlceras o gangrena (9%), trombosis arterial de extremidades (7%), trombosis retinal (7%), isquemia visceral (6%), demencia por múltiples infartos (3%).\nNeurológicas: migraña (20%), epilepsia (7%), corea (1%), ataxia cerebelosa (1%), mielopatía transversa (0.5%).\nOsteoarticulares: artralgias (39%), artritis (27%).\nObstétricas: preeclampsia (10%), eclampsia (4%).\nFetales: pérdida fetal precoz (35%), pérdida fetal tardía (17%), parto prematuro (11%).\nHematológicas: trombocitopenia (30%), anemia hemolítica autoinmunitaria (10%).\n\n📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, Capítulo 357.",
