    "explanation": "Respuesta correcta: La enfermedad cardiovascular ocurre exclusivamente por la presencia de factores de riesgo tradicionales.\n🧠 ANÁLISIS DE LA PREGUNTA\nEl texto indica que el riesgo cardiovascular permanece elevado incluso después de ajustar por factores tradicionales, lo que sugiere un papel importante de la inflamación crónica.\n🔑 CONCEPTOS CLAVE\nPrincipal causa de muerte.\nMayor aterosclerosis.\nInsuficiencia cardíaca casi al doble.\nInflamación y riesgo cardiovascular.\n⚡ REPASO ACTIVO\nLa enfermedad cardiovascular es la principal causa de muerte en la AR.\nMayor incidencia de enfermedad coronaria y aterosclerosis carotídea.\nLa insuficiencia cardíaca congestiva es aproximadamente el doble de frecuente.\nLos marcadores inflamatorios elevados aumentan el riesgo cardiovascular.\n\n📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, Capítulo 359.",
    "materia": "Medicina Interna",
    "semana": 14,
    "tema": "Reumatología",
