    "correctOptionIndex": 2,
    "explanation": "Respuesta correcta: La inflamación crónica, el uso prolongado de glucocorticoides y la inmovilización.\n🧠 ANÁLISIS DE LA PREGUNTA\nEl texto menciona que la osteoporosis en la AR es multifactorial: inflamación sistémica, glucocorticoides e inmovilización por discapacidad.\n🔑 CONCEPTOS CLAVE\nInflamación crónica.\nGlucocorticoides.\nInmovilización.\nMayor riesgo de fracturas.\n⚡ REPASO ACTIVO\nLa osteoporosis es más frecuente en la AR.\nExiste mayor riesgo de fracturas por fragilidad.\nContribuyen la inflamación sistémica, el uso prolongado de glucocorticoides y la inmovilización.\nLas fracturas de cadera se asocian con mayor discapacidad y mortalidad.\n\n📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, Capítulo 359.",
