    "id": "reumato_q65",
    "text": "¿Cuál de los siguientes componentes constituye el principal glucosaminoglucano responsable de la viscosidad del líquido sinovial?",
    "options": [
      "Ácido hialurónico",
      "Fibronectina",
      "Laminina",
      "Lubricina",
      "Colágeno"
    ],
    "correctOptionIndex": 0,
    "explanation": "Respuesta correcta: Ácido hialurónico\n🧠 ANÁLISIS DE LA PREGUNTA\nEl texto señala que el ácido hialurónico es el principal glucosaminoglucano del líquido sinovial y contribuye a su viscosidad; junto con la lubricina facilita la lubricación del cartílago.\n🔑 CONCEPTOS CLAVE\nÁcido hialurónico = viscosidad.\nLubricina = lubricación.\nLíquido sinovial = ultrafiltrado del plasma.\n⚡ REPASO ACTIVO\nLa membrana sinovial contiene sinoviocitos tipo A (derivados de macrófagos) y tipo B (derivados de fibroblastos).\nEl líquido sinovial es un ultrafiltrado del plasma.\nSus principales componentes son ácido hialurónico y lubricina.\nEl ácido hialurónico aporta viscosidad y la lubricina lubrica la superficie del cartílago.\n\n📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, Capítulo 359.",
