    "explanation": "Respuesta correcta: Los glucocorticoides deben mantenerse indefinidamente a dosis altas porque previenen la progresión estructural de la enfermedad.\n🧠 ANÁLISIS DE LA PREGUNTA\nEl texto recomienda utilizar glucocorticoides a la menor dosis y durante el menor tiempo posible, buscando instaurar un DMARD eficaz para evitar su uso crónico.\n🔑 CONCEPTOS CLAVE\nMetotrexato = primera elección.\nAINE = tratamiento sintomático.\nEvitar glucocorticoides crónicos.\n⚡ REPASO ACTIVO\nEl metotrexato es el DMARD de primera elección.\nLos AINE son complementarios para el control sintomático.\nLos glucocorticoides deben emplearse a la menor dosis y por el menor tiempo posible.\nMuchos pacientes requieren terapia combinada según la actividad de la enfermedad.\n\n📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, Capítulo 359.",
