    "explanation": "Respuesta correcta: Prueba de ANA\n🧠 ANÁLISIS DE LA PREGUNTA\nEl texto señala que la enfermedad de Raynaud primaria se sustenta, entre otros criterios, por la prueba de ANA negativa; por ello, la determinación de ANA forma parte de la evaluación cuando se sospecha un Raynaud secundario.\n🔑 CONCEPTOS CLAVE\nSolicitar ANA en la evaluación.\nANA negativo favorece Raynaud primario.\nANA positivo obliga a investigar enfermedades del tejido conectivo.\n⚡ REPASO ACTIVO\nManifestación no cutánea más frecuente: fenómeno de Raynaud.\nDesencadenantes: frío, estrés emocional y vibración.\nCambios de color: palidez → cianosis → hiperemia.\nLa evaluación incluye la prueba de ANA para diferenciar Raynaud primario del secundario.\n\n📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, Capítulo 360.",
