    "explanation": "Respuesta correcta: Engrosamiento cutáneo simétrico bilateral\n🧠 ANÁLISIS DE LA PREGUNTA\nEl engrosamiento cutáneo simétrico bilateral constituye el rasgo distintivo de la esclerosis sistémica y permite diferenciarla de otras enfermedades del tejido conjuntivo.\n🔑 CONCEPTOS CLAVE\nEs el signo clínico característico de la enfermedad.\nComienza en los dedos y progresa de distal a proximal.\nSe acompaña de fibrosis cutánea y pérdida de la movilidad.\n⚡ REPASO ACTIVO\nRasgo distintivo: engrosamiento cutáneo simétrico bilateral.\nInicio en los dedos con progresión proximal.\nPuede asociarse a alteraciones de la pigmentación (\"sal y pimienta\").\nLa fibrosis ocasiona contracturas y disminución de la movilidad.\n\n📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, Capítulo 360.",
