    "options": [
      "El fenómeno de Raynaud se presenta aproximadamente en el 37% de los pacientes y en algunos precede a los síntomas de sequedad.",
      "La afectación pulmonar puede manifestarse como enfermedad de las vías respiratorias de pequeño calibre o neumonitis linfocítica intersticial.",
      "La neuropatía periférica constituye una de las manifestaciones extraglandulares más frecuentes, con una prevalencia cercana al 25%.",
      "La glomerulonefritis es una manifestación mediada por complejos inmunitarios y suele ser de tipo membranoproliferativa.",
      "El linfoma predominante es el linfoma glandular tipo MALT."
    ],
    "correctOptionIndex": 2,
    "explanation": "Respuesta correcta: La neuropatía periférica constituye una de las manifestaciones extraglandulares más frecuentes, con una prevalencia cercana al 25%.\n🧠 ANÁLISIS DE LA PREGUNTA\nLa neuropatía periférica tiene una prevalencia aproximada del 2%, por lo que no constituye una de las manifestaciones más frecuentes. Las demás afirmaciones reproducen fielmente el cuadro.\n🔑 CONCEPTOS CLAVE\nRaynaud: 37%.\nNeuropatía periférica: 2%.\nGlomerulonefritis membranoproliferativa.\nLinfoma MALT.\n⚡ REPASO ACTIVO\nManifestaciones extraglandulares (prevalencia)\nInespecíficas\nFatiga/mialgias: 25% (fibromialgia).\nArtralgias o artritis: 60% (casi nunca erosiva; artropatía de Jaccoud).\nFenómeno de Raynaud: 37% (en un 33% precede a los síntomas de sequedad).\nPeriepiteliales\nAfectación pulmonar: 14% (enfermedad de vías respiratorias de pequeño calibre/neumonitis linfocítica intersticial).\nAfectación renal: 9% (nefropatía intersticial generalmente asintomática).\nAfectación hepática: 6% (cirrosis biliar primaria de estadio 1).\nMediadas por complejos inmunitarios\nVasculitis de vasos de pequeño calibre: 9% (púrpura, lesiones urticariformes).\nNeuropatía periférica: 2% (polineuropatía sensitiva o sensitivomotora).\nGlomerulonefritis: 2% (membranoproliferativa).\nLinfoma\nLinfoma: 6% (predomina el linfoma glandular MALT).\n\n📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 361. Cuadro 361-1. Prevalencia de las manifestaciones extraglandulares en el síndrome de Sjögren primario.",
    "materia": "Medicina Interna",
