    "explanation": "Respuesta correcta: La complicación más grave de la enfermedad raquídea es la artrosis facetaria.\n🧠 ANÁLISIS DE LA PREGUNTA\nLa afirmación es incorrecta. El texto señala que la complicación más grave de la enfermedad raquídea es la fractura de la columna, que puede ocurrir incluso tras traumatismos de baja energía debido a la rigidez y osteoporosis vertebral.\nLas demás afirmaciones corresponden fielmente al fragmento:\nSchober modificado evalúa la flexión lumbar.\nExpansión torácica normal ≥ 2,5 cm.\nLa uveítis anterior aguda es la manifestación extraarticular más frecuente.\nLa artritis periférica ocurre hasta en el 30% de los pacientes.\n🔑 CONCEPTOS CLAVE\nSchober modificado.\nExpansión torácica ≥ 2,5 cm.\nUveítis anterior.\nFractura vertebral.\n⚡ REPASO ACTIVO\nExploración física\nPérdida de movilidad lumbar.\nDisminución de la expansión torácica.\nPrueba modificada de Schober.\nExpansión torácica normal ≥ 2,5 cm.\nFlexión lateral normal >10 cm.\nManifestaciones extraarticulares\nUveítis anterior aguda (más frecuente).\nInflamación intestinal subclínica.\nPsoriasis.\nArtritis periférica (hasta 30%).\nCardiopatía isquémica (riesgo aumentado).\nInsuficiencia aórtica.\nBloqueo cardíaco.\nComplicaciones\nFractura de columna (complicación más grave).\nSeudartrosis.\nFibrosis de lóbulos superiores pulmonares.\nSíndrome de cola de caballo.\n\n📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 362. Manifestaciones clínicas.",
