    "correctOptionIndex": 2,
    "explanation": "Respuesta correcta: Uveítis anterior aguda.\n🧠 ANÁLISIS DE LA PREGUNTA\nLa uveítis anterior aguda es la manifestación extraarticular más frecuente de la espondilitis anquilosante. Puede presentarse hasta en el 50% de los pacientes e incluso preceder a las manifestaciones articulares.\n🔑 CONCEPTOS CLAVE\nManifestación extraarticular más frecuente: uveítis anterior aguda.\nSuele ser unilateral y recurrente.\nPuede alternar de un ojo al otro.\nPuede aparecer antes de la espondilitis.\n⚡ REPASO ACTIVO\nUveítis anterior aguda\nSe presenta hasta en el 50%.\nPuede preceder a la espondilitis.\nGeneralmente unilateral.\nEpisodios recurrentes.\nFotofobia.\nDolor ocular.\nEnrojecimiento alrededor del iris.\nPuede alternar entre ambos ojos.\n\n📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 362. Manifestaciones clínicas.",
