    "correctOptionIndex": 1,
    "explanation": "Respuesta correcta: Dactilitis (\"dedo en salchicha\") con artritis asimétrica de predominio en miembros inferiores.\n🧠 ANÁLISIS DE LA PREGUNTA\nLa artritis reactiva se caracteriza por una artritis asimétrica y aditiva, que afecta principalmente las articulaciones de las extremidades inferiores (rodillas, tobillos, subtalares, metatarsofalángicas e interfalángicas del pie). La dactilitis constituye una manifestación muy característica.\n🔑 CONCEPTOS CLAVE\nArtritis asimétrica.\nPredominio en miembros inferiores.\nDactilitis.\nEntesitis.\nFascitis plantar y tendinitis aquílea.\n⚡ REPASO ACTIVO\nManifestaciones clínicas\nArtritis asimétrica y aditiva.\nPredominio en:\nRodillas.\nTobillos.\nSubtalares.\nMetatarsofalángicas.\nInterfalángicas del pie.\nDactilitis (\"dedo en salchicha\").\nEntesitis.\nTendinitis aquílea.\nFascitis plantar.\nDolor lumbar y glúteo.\nUretritis, prostatitis, cervicitis o salpingitis.\nConjuntivitis y uveítis anterior.\nÚlceras orales.\nQueratodermia blenorrágica.\nBalanitis circinada.\nOnicólisis e hiperqueratosis ungueal.\n\n📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 362. Artritis reactiva: Manifestaciones clínicas.",
    "materia": "Medicina Interna",
    "semana": 14,
    "tema": "Reumatología",
