    "correctOptionIndex": 3,
    "explanation": "Respuesta correcta: La lesión renal se caracteriza por depósitos abundantes de complejos inmunitarios.\n🧠 ANÁLISIS DE LA PREGUNTA\nEn la lesión renal de la granulomatosis con poliangitis no se identifican depósitos de complejos inmunitarios. El compromiso renal comienza típicamente como glomerulonefritis focal y segmentaria y puede evolucionar a una forma rápidamente progresiva con semilunas.\n🔑 CONCEPTOS CLAVE\nPulmón: nódulos múltiples, bilaterales y cavitados.\nRiñón: glomerulonefritis focal y segmentaria.\nEvolución posible: semilunas y deterioro rápido.\nSin depósitos de complejos inmunitarios.\nEstenosis subglótica: enfermedad activa o cicatrización.\n⚡ REPASO ACTIVO\nGranulomatosis con poliangitis: patrón de órganos\nSuperior: senos paranasales, nariz, oído medio y región subglótica.\nInferior: pulmón con infiltrados nodulares cavitados.\nRenal: glomerulonefritis focal y segmentaria, rápidamente progresiva y con semilunas.\nHistología: vasculitis granulomatosa necrosante de vasos pequeños.\nInmunopatología renal: ausencia de depósitos de complejos inmunitarios.\n\n📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 363. Granulomatosis con poliangitis: Histopatología y patogenia; Manifestaciones clínicas y datos de laboratorio. Cuadro 363-5.",
