    "correctOptionIndex": 1,
    "explanation": "Respuesta correcta: 🧠 ANÁLISIS DE LA PREGUNTA\nSegún el cuadro de manifestaciones clínicas del capítulo, el aparato musculoesquelético (64%) es el sistema afectado con mayor frecuencia, seguido por los riñones (60%) y el sistema nervioso periférico (51%).\n🔑 CONCEPTOS CLAVE\nAparato musculoesquelético: 64%.\nRiñones: 60%.\nSistema nervioso periférico: 51%.\n⚡ REPASO ACTIVO\nAparato musculoesquelético (64%) → artritis, artralgias, mialgias.\nRiñones (60%) → insuficiencia renal, hipertensión.\nSistema nervioso periférico (51%) → neuropatía periférica, mononeuritis múltiple.\nTubo digestivo (44%) → dolor abdominal, náuseas, vómitos, hemorragia, infarto intestinal, perforación, colecistitis, infarto hepático e infarto pancreático.\nPiel (43%) → erupción, púrpura, nódulos, infartos cutáneos, livedo reticular, fenómeno de Raynaud.\nCorazón (36%) → insuficiencia congestiva, infarto de miocardio.\nAparato genitourinario (25%) → dolor testicular, ovárico o de epidídimo.\nSistema nervioso central (23%) → apoplejía, alteración del estado mental y convulsiones.\n\n📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 363.",
