    "explanation": "Respuesta correcta: 🧠 ANÁLISIS DE LA PREGUNTA\nEl diagnóstico se basa en demostrar los hallazgos característicos de vasculitis mediante biopsia del órgano afectado. La arteriografía se reserva cuando no existe tejido accesible para biopsia.\n🔑 CONCEPTOS CLAVE\nLa biopsia confirma el diagnóstico.\nLa arteriografía es alternativa cuando no puede realizarse biopsia.\nNo existen métodos serológicos diagnósticos.\n⚡ REPASO ACTIVO\nDiagnóstico basado en biopsia del órgano afectado.\nMayor rendimiento en piel, testículo y nervio/músculo sintomáticos.\nSi no hay tejido accesible → arteriografía con contraste por catéter.\nHallazgos angiográficos: aneurismas, estenosis y obliteración vascular.\nLos aneurismas no son patognomónicos.\n\n📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 363.",
