    "correctOptionIndex": 1,
    "explanation": "Respuesta correcta: 🧠 ANÁLISIS DE LA PREGUNTA\nLa artritis aguda constituye la manifestación clínica inicial más frecuente de la gota. Al inicio suele afectar una sola articulación y, con la evolución, puede comprometer varias.\n🔑 CONCEPTOS CLAVE\n•\tManifestación inicial: artritis aguda.\n•\tHabitualmente monoarticular.\n•\tPrimera MTF afectada en 70–90%.\n⚡ REPASO ACTIVO\n•\tManifestación inicial: artritis aguda.\n•\tInicio generalmente monoarticular.\n•\tPrimera articulación metatarsofalángica (podagra): 70–90%.\n•\tPosteriormente puede afectar tarso, tobillo y rodilla.\n•\tCrisis nocturnas o de madrugada.\n•\tResolución espontánea en 1–2 semanas.\n\n📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 372.",
