    "correctOptionIndex": 3,
    "explanation": "Respuesta correcta: 🧠 ANÁLISIS DE LA PREGUNTA\nDurante un ataque agudo se utilizan AINE, colchicina y glucocorticoides. El alopurinol es un tratamiento reductor del ácido úrico para el manejo crónico y no constituye tratamiento del episodio agudo.\n🔑 CONCEPTOS CLAVE\n•\tAINE.\n•\tColchicina.\n•\tGlucocorticoides.\n⚡ REPASO ACTIVO\nTratamiento de la gota aguda:\n•\tAINE (indometacina, naproxeno, ibuprofeno, celecoxib).\n•\tColchicina.\n•\tGlucocorticoides orales, intramusculares o intraarticulares.\n•\tAnakinra cuando los tratamientos convencionales están contraindicados o han fracasado.\n\n📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 372.",
