    "correctOptionIndex": 1,
    "explanation": "Respuesta correcta: 🧠 ANÁLISIS DE LA PREGUNTA\nEl alopurinol es el inhibidor de la xantina oxidasa de primera línea para reducir el ácido úrico sérico. El probenecid es un uricosúrico de segunda línea.\n🔑 CONCEPTOS CLAVE\n•\tAlopurinol = primera línea.\n•\tObjetivo: ácido úrico <5–6 mg/dL.\n•\tProbenecid = segunda línea.\n⚡ REPASO ACTIVO\nTratamiento reductor del ácido úrico:\n•\tObjetivo: ácido úrico <300–360 µmol/L (5–6 mg/dL).\n•\tPrimera línea: alopurinol.\n•\tAlternativa: febuxostat.\n•\tSegunda línea: probenecid.\n•\tIniciar en pacientes con tofos, artritis gotosa crónica o cálculos de ácido úrico.\n\n📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 372.",
