    "correctOptionIndex": 2,
    "explanation": "Respuesta correcta: 🧠 ANÁLISIS DE LA PREGUNTA\nEl alelo HLA-B*5801 se asocia a un riesgo significativamente mayor de reacciones cutáneas graves (como síndrome de Stevens-Johnson y necrólisis epidérmica tóxica), por lo que se recomienda su detección en poblaciones de alto riesgo antes de iniciar alopurinol.\n🔑 CONCEPTOS CLAVE\n•\tHLA-B*5801.\n•\tStevens-Johnson.\n•\tNecrólisis epidérmica tóxica.\n⚡ REPASO ACTIVO\n•\tAlopurinol: inhibidor de la xantina oxidasa.\n•\tIniciar con dosis bajas y titular progresivamente.\n•\tReacciones cutáneas graves: síndrome de Stevens-Johnson y necrólisis epidérmica tóxica.\n•\tFactores de riesgo: HLA-B*5801, dosis inicial elevada en ERC, edad avanzada y sexo femenino.\n•\tSi HLA-B*5801 es positivo, utilizar un fármaco alternativo.\n\n📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 372.",
