    "correctOptionIndex": 2,
    "explanation": "Respuesta correcta: 🧠 ANÁLISIS DE LA PREGUNTA\nLas principales manifestaciones clínicas de la osteoporosis son las fracturas vertebrales y de cadera, aunque las fracturas pueden aparecer en cualquier hueso tras traumatismos de baja energía.\n🔑 CONCEPTOS CLAVE\n•\tFracturas vertebrales.\n•\tFractura de cadera.\n•\tTraumatismos de baja energía.\n⚡ REPASO ACTIVO\n•\tFracturas vertebrales.\n•\tFracturas de cadera.\n•\tPueden ocurrir en cualquier hueso.\n•\tSe producen con traumatismos equivalentes a una caída desde la propia altura.\n•\tSe excluyen habitualmente cráneo, cara, manos y pies.\n\n📖 Referencia: Harrison, Principios de Medicina Interna, 21.ª edición, capítulo 411.",
